<script setup>
import { computed } from 'vue'
import { logLatency } from '../utils/logQueryState'
import { observedNumber, observedBoolean, observedText, observationStages, observationVersion, observationAttempts, observationSummary, observationAttemptLabel, attemptStatusLabel, finalUpstreamFailure, observedErrorParameter, toolPolicyObservation, boundSelectionObservation, attemptPhase, modelComparison, truncationLabel, websocketWarmupLabel } from '../utils/logObservationState'
import { passiveTimingSource } from '../utils/logPassiveObservation'
const props = defineProps({ record: Object })
const summary = computed(() => observationSummary(props.record))
const attempts = computed(() => observationAttempts(props.record))
const finalFailure = computed(() => finalUpstreamFailure(props.record))
const milliseconds = value => observedNumber(value) === null ? '未记录' : logLatency(value)
</script>
<template>
  <section class="log-observation-details" aria-label="链路观测详情">
    <h3>链路观测</h3>
    <dl class="observation-fields observation-models"><dt>入站请求模型</dt><dd>{{ observedText(record?.model) || '未记录' }}</dd><dt>最后实际发送模型</dt><dd>{{ summary.sent || '未记录' }}</dd><dt>真实响应返回模型</dt><dd>{{ summary.returned || '未记录' }}</dd><dt>请求 / 发送比较</dt><dd>{{ modelComparison(record?.model, record?.sent_model) }}</dd><dt>发送 / 返回比较</dt><dd>{{ modelComparison(record?.sent_model, record?.returned_model) }}</dd><dt>兼容上游模型</dt><dd>{{ record?.upstream_model || '未记录' }}<small v-if="record?.upstream_model">来源：{{ record.upstream_model_source || '未记录' }}</small></dd></dl>
    <p class="observation-note">发送模型取实际最后一次派发。App Server 的模型由官方线程确认，来源标为 app_server_thread / settings / rerouted；其他接口取响应字段。模型名称不是底层模型身份的独立证明。</p>
    <dl class="observation-fields observation-paths"><dt>入站标准路径</dt><dd>{{ summary.inbound || '未记录' }}</dd><dt>上游标准路径</dt><dd>{{ summary.upstream || '未记录' }}</dd></dl>
    <dl class="observation-fields observation-warmup"><dt>WebSocket 预热</dt><dd>{{ websocketWarmupLabel(record?.websocket_warmup) }}<small>{{ record?.websocket_warmup === true ? '来源：response.create 的 generate=false。' : record?.websocket_warmup === false ? '来源：response.create 的 generate=true 或字段缺省。' : '未取得明确布尔观测，不能据此判断为普通生成。' }}</small></dd></dl>
    <h4>独立阶段耗时</h4><dl class="observation-fields observation-stage-times"><template v-for="[key,label] in observationStages" :key="key"><dt>{{ label }}</dt><dd>{{ milliseconds(record?.[key]) }}</dd></template><dt>计时来源</dt><dd>{{ passiveTimingSource(record?.timing_source) }}</dd></dl><p class="observation-note">阶段可能重叠，不能累加为总耗时。网关授权不等于 OAuth 刷新耗时：HTTP 记录入站密钥识别，WebSocket 记录既有授权校验及其中的存储读取。账号选择可能包含等待锁和 OAuth。</p><p class="observation-note">{{ record?.request_type === 'websocket' ? '响应传递：本轮首个匹配的上游事件至终态观测，不包含终态帧向下游的最后写出。' : '响应传递：HTTP 上游响应头返回至处理结束，包含读取响应体、本地解析及下游写出。' }}未观测的 DNS、连接或 TLS 耗时不作推断。</p>
    <section class="observation-attempts" aria-label="请求派发尝试"><div class="observation-attempt-heading"><h4>派发尝试</h4><span>{{ observationAttemptLabel(record) }}</span></div><p class="observation-note">实际调用发送或拨号不等于上游已收到或接受。协议状态记录逻辑结果；HTTP 只展示实际响应头，未采集时保持未知。按开始顺序最多记录 4 次，OAuth 刷新与请求派发分别展示。请求派发耗时截至响应头或传输错误，OAuth 刷新耗时截至交换结果处理完成。</p>
      <p v-if="!attempts.length" class="observation-note">{{ summary.attemptCount === 0 ? '该记录采用实际网络派发观测，处理在发送前结束。' : '没有可用的尝试观测，不表示发生 0 次发送或重试。' }}</p>
      <ol v-else class="observation-attempt-list"><li v-for="(attempt,index) in attempts" :key="index"><div class="attempt-heading"><strong>{{ attempt.attempt === null ? '序号未记录' : '尝试 ' + attempt.attempt }} · {{ attemptPhase(attempt.phase) }}</strong><span>{{ attemptStatusLabel(attempt) }}</span></div><dl class="observation-fields"><dt>标准端点</dt><dd>{{ attempt.endpoint || '未记录' }}</dd><dt>尝试耗时</dt><dd>{{ milliseconds(attempt.duration_ms) }}</dd><dt>响应头等待</dt><dd>{{ milliseconds(attempt.header_ms) }}</dd><dt>错误来源</dt><dd>{{ attempt.error_source || '未记录' }}</dd><dt>有限错误分类</dt><dd>{{ attempt.error_code || '未记录' }}</dd></dl></li></ol>
      <dl v-if="finalFailure.code || finalFailure.source" class="observation-fields"><dt>最终生成错误</dt><dd><span>{{ finalFailure.source || '来源未记录' }}</span> · <code>{{ finalFailure.code || '代码未记录' }}</code></dd></dl>
      <p class="observation-note" :class="{ 'observation-warning': record?.attempts_truncated === true }">尝试记录：{{ truncationLabel(record?.attempts_truncated) }}{{ record?.attempts_truncated === true ? '；后续尝试未包含在此列表中。' : '。' }}</p>
      <p v-if="Array.isArray(record?.attempts) && record.attempts.length > 4" class="observation-warning">响应超出约定上限，当前仅展示前 4 条。</p>
    </section>
    <dl v-if="observedErrorParameter(record)" class="observation-fields observation-error-parameter"><dt>拒绝参数</dt><dd><code>{{ observedErrorParameter(record) }}</code></dd></dl>
    <details v-if="boundSelectionObservation(record)" class="observation-bound-selection"><summary>会话绑定观测 <span>{{ boundSelectionObservation(record).summary }}</span></summary><dl class="observation-fields"><template v-for="[label,value] in boundSelectionObservation(record).rows" :key="label"><dt>{{ label }}</dt><dd>{{ value }}</dd></template></dl><p class="observation-note">这是本次选择时使用的账号快照，不代表当前账号状态。授权候选按启用状态和本密钥分组筛选，不保证可立即使用，也不等于实际派发次数；完整明文仍须通过其他检查后才能迁移。</p></details>
    <details v-if="toolPolicyObservation(record)" class="observation-tool-policy"><summary>工具策略观测 <span>{{ toolPolicyObservation(record).summary }}</span></summary><dl class="observation-fields"><template v-for="[label,value] in toolPolicyObservation(record).rows" :key="label"><dt>{{ label }}</dt><dd>{{ value }}</dd></template></dl><p class="observation-note">计数来自实际工具目录。精确匹配声明不代表被工具策略允许；选择策略、并行限制和整轮校验仍可能拒绝。</p></details>
    <dl class="observation-fields observation-schema"><dt>观测结构版本</dt><dd>{{ observationVersion(record) ?? '未记录' }}</dd><dt>用量结构来源</dt><dd>{{ observedText(record?.usage_schema_source) || '未记录' }}</dd><dt>错误文本截断</dt><dd>{{ truncationLabel(record?.error_truncated) }}</dd></dl>
    <p v-if="observedBoolean(record?.error_truncated) === true" class="observation-warning">保存的错误文本已截断，不能视为完整原始错误正文。</p>
  </section>
</template>
<style scoped>
:is(.observation-tool-policy,.observation-bound-selection){margin-top:16px;border-top:1px solid var(--card-border);padding-top:12px}:is(.observation-tool-policy,.observation-bound-selection) summary{cursor:pointer;color:var(--text-2);overflow-wrap:anywhere}:is(.observation-tool-policy,.observation-bound-selection) summary span{margin-left:8px;color:var(--text-3);font-size:11px}:is(.observation-tool-policy,.observation-bound-selection)[open] summary{margin-bottom:12px}:is(.observation-tool-policy,.observation-bound-selection) .observation-fields{margin-bottom:8px}
.log-observation-details { border-top:1px solid var(--card-border);padding-top:17px;margin-top:18px;min-width:0;color:var(--text-2);font-size:12px;line-height:1.7 }.log-observation-details h3{font-size:13px;font-weight:500;color:var(--text-1);margin:0 0 13px}.log-observation-details h4{font-size:12px;font-weight:500;color:var(--text-2);margin:16px 0 10px}.observation-fields{display:grid;grid-template-columns:128px minmax(0,1fr);gap:10px 12px;margin:0 0 14px}.observation-fields dt{color:var(--text-3)}.observation-fields dd{margin:0;overflow-wrap:anywhere;font-variant-numeric:tabular-nums}.observation-fields small{display:block;color:var(--text-3);font-size:11px}.observation-note{color:var(--text-3);font-size:12px;line-height:1.8;margin:10px 0}.observation-attempt-heading,.attempt-heading{display:flex;align-items:baseline;gap:8px;flex-wrap:wrap;justify-content:space-between}.observation-attempt-heading>span,.attempt-heading>span{font-size:11px;color:var(--text-3)}.observation-attempt-list{padding:0;list-style:none;margin:12px 0}.observation-attempt-list>li{padding:12px 0;border-top:1px solid var(--card-border)}.attempt-heading{margin-bottom:10px}.attempt-heading strong{font-size:12px;font-weight:500;overflow-wrap:anywhere}.observation-attempt-list .observation-fields{margin:0}.observation-schema{margin-top:17px;padding-top:15px;border-top:1px solid var(--card-border)}.observation-warning{color:var(--warning,#a66c11);font-size:12px;line-height:1.8;overflow-wrap:anywhere}@media(max-width:500px){.observation-fields{grid-template-columns:105px minmax(0,1fr);gap:9px}.attempt-heading>span{font-size:12px}}
</style>
